  ('83dc1613-cbf4-4137-bf5d-154cddce66ea', 'f69faffd-9115-49bc-92f4-609f3915d37f', 'cb555b69-01b5-407c-9b71-eb6015992ca2', 'Fast lunch, clean flavours, and the roast skin had a nice bite.', '2026-03-31 01:00:00.000000', NULL, 0, 1, false, 'Quick Chicken Rice Stop', false, false, NULL, true),
  ('5da768fc-ae62-4e59-b9de-b0aa119e431b', '94971227-2415-4fb8-aeb8-d3b144f56d81', '045ad4a1-3ee4-4375-b339-ea9ad2392e92', 'A little messy, very satisfying, and worth ordering with extra fries. #burger #western', '2026-03-30 06:00:00.000000', NULL, 2, 0, false, 'Fries and Burger Combo', false, false, NULL, true),
  ('2505dade-9213-4787-b573-6b71eb76c4c7', '3af36f64-3e7f-4bd5-b297-7fde49c903e4', '571c483e-615d-419d-978d-e4214f35ebd9', 'This bowl hit the spot after a long day. Warm, savoury, and properly comforting.', '2026-03-30 02:00:00.000000', NULL, 2, 1, false, 'Comfort Bowl After Work', false, false, NULL, true)
